Method.Source:
public void initValue()
{
    super();
    this.Quantity = 1;
    this.UnitPrice = 0;
    this.LineAmount = 0;
}

private void calculateLineAmount()
{
    this.LineAmount = this.Quantity * this.UnitPrice;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);
    switch (_fieldId)
    {
        case fieldNum(SOrderLine, Quantity):
        case fieldNum(SOrderLine, UnitPrice):
            this.calculateLineAmount();
            break;
    }
}

public boolean validateField(FieldId _fieldId)
{
    boolean ret = super(_fieldId);
    switch (_fieldId)
    {
        case fieldNum(SOrderLine, Quantity):
            if (this.Quantity <= 0)
            {
                ret = checkFailed("@SLabels:SQuantityMustBePositive");
            }
            else if (this.Quantity > 100)
            {
                ret = checkFailed("@SLabels:SQuantityCannotExceedMaximum");
            }
            else if (this.UnitPrice == 0 && this.Quantity > 10)
            {
                ret = checkFailed("@SLabels:SFreeUnitQuantityExceedMax");
            }
            break;
        case fieldNum(SOrderLine, UnitPrice):
            if (this.UnitPrice < 0)
            {
                ret = checkFailed("@SLabels:SUnitPriceCannotBeNegative");
            }
            break;
        case fieldNum(SOrderLine, OrderID):
            if (this.RecId && this.OrderID != this.orig().OrderID)
            {
                ret = checkFailed("@SLabels:SOrderIdCannotBeChanged");
            }
            break;
        case fieldNum(SOrderLine, LineNum):
            if (this.RecId && this.LineNum != this.orig().LineNum)
            {
                ret = checkFailed("@SLabels:SLineNumCannotBeChanged");
            }
            break;
        case fieldNum(SOrderLine, ItemID):
            if (this.RecId && this.ItemID != this.orig().ItemID)
            {
                ret = checkFailed("@SLabels:SItemIdCannotBeChanged");
            }
            break;
    }
    return ret;
}

public boolean validateWrite()
{
    boolean ret = super();
    SOrderTable orderTable;
    SOrderLine orderLine;
    ITMItemCode itmItemCode;
    int64 lineCount;

    if (!ret)
    {
        return false;
    }

    if (!this.OrderID)
    {
        return checkFailed("@SLabels:SOrderIdRequired");
    }

    orderTable = SOrderTable::find(this.OrderID);
    if (!orderTable.RecId)
    {
        return checkFailed("@SLabels:SOrderNotFound");
    }

    if (orderTable.Status != SOrderStatus::Draft)
    {
        return checkFailed("@SLabels:SOnlyDraftOrderCanBeModified");
    }

    if (!this.ItemID)
    {
        return checkFailed("@SLabels:SItemIdRequired");
    }

    if (this.Quantity <= 0)
    {
        return checkFailed("@SLabels:SQuantityMustBePositive");
    }

    if (this.Quantity > 100)
    {
        return checkFailed("@SLabels:SQuantityCannotExceedMaximum");
    }

    if (this.UnitPrice < 0)
    {
        return checkFailed("@SLabels:SUnitPriceCannotBeNegative");
    }

    if (this.UnitPrice > 0)
    {
        select firstonly itmItemCode
            where itmItemCode.Code == this.ItemID;

        if (itmItemCode.RecId && itmItemCode.MinimumPrice > 0
            && this.UnitPrice < itmItemCode.MinimumPrice)
        {
            return checkFailed(strFmt("Unit price for %1 must be at least %2.",
                this.ItemID, itmItemCode.MinimumPrice));
        }
    }

    if (this.UnitPrice == 0 && this.Quantity > 10)
    {
        return checkFailed("@SLabels:SFreeUnitQuantityExceedMax");
    }

    // Max 5 lines per order
    if (!this.RecId)
    {
        select count(RecId) from orderLine
            where orderLine.OrderID == this.OrderID;
        lineCount = orderLine.RecId;

        if (lineCount >= 5)
        {
            return checkFailed("@SLabels:SMaximumLineCountExceeded");
        }
    }

    return true;
}

public boolean validateDelete()
{
    boolean ret = super();
    SOrderTable orderTable;

    if (!ret)
    {
        return false;
    }

    orderTable = SOrderTable::find(this.OrderID);
    if (orderTable.Status != SOrderStatus::Draft)
    {
        ret = checkFailed("@SLabels:SOnlyDraftOrderCanBeDeleted");
    }

    return ret;
}

public void insert()
{
    SOrderTable orderTable;

    if (!this.LineNum)
    {
        this.LineNum = SOrderLine::nextLineNum(this.OrderID);
    }

    this.calculateLineAmount();
    ttsBegin;
    super();
    orderTable = SOrderTable::find(this.OrderID, true);
    if (orderTable.RecId)
    {
        orderTable.calculateTotalAmount();
        orderTable.update();
    }
    ttsCommit;
}

public void update()
{
    SOrderTable orderTable;
    this.calculateLineAmount();
    ttsBegin;
    super();
    orderTable = SOrderTable::find(this.OrderID, true);
    if (orderTable.RecId)
    {
        orderTable.calculateTotalAmount();
        orderTable.update();
    }
    ttsCommit;
}

public void delete()
{
    SOrderID orderId = this.OrderID;
    SOrderTable orderTable;
    ttsBegin;
    super();
    orderTable = SOrderTable::find(orderId, true);
    if (orderTable.RecId)
    {
        orderTable.calculateTotalAmount();
        orderTable.update();
    }
    ttsCommit;
}

/// <summary>
/// Calculates the next line number for the sales order line.
/// </summary>
/// <param name="_orderId">The sales order ID.</param>
/// <returns>The next available line number.</returns>
public static LineNum nextLineNum(SOrderID _orderId)
{
    SOrderLine orderLine;

    select maxOf(LineNum) from orderLine
        where orderLine.OrderID == _orderId;

    return orderLine.LineNum + 1;
}
